[Better Approach] Using Two Pointers Technique - O(nlogn) Time and O(1) SpaceThe idea is to sort the input array and use two-pointer technique. Maintain two pointers, say left and right and initialize them to the first and last element of the array respectively. According to the sum of left and right pointers, we can have three cases:arr[left] + arr[right] < target: Increase the pair sum by moving the left pointer towards right.arr[left] + arr[right] > target: Decrease the pair sum by moving the right pointer towards left.arr[left] + arr[right] = target: We have found a pair whose sum is equal to target. We can find the product of the count of both the elements and add them to the result.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int countPairs(vector<int> &arr, int target) {
    int res = 0;
    int n = arr.size();
    int left = 0, right = n - 1;

    // Sort the array before applying 
    // two-pointer technique
    sort(arr.begin(), arr.end());
    while (left < right) {

        // If sum is greater 
        if (arr[left] + arr[right] < target)
            left++;

        // If sum is lesser
        else if (arr[left] + arr[right] > target)
            right--;

        // If sum is equal
        else {

            int cnt1 = 0, cnt2 = 0;
            int ele1 = arr[left], ele2 = arr[right];

            // Count frequency of first element of the pair
            while (left <= right and arr[left] == ele1) {
                left++;
                cnt1++;
            }

			// Count frequency of second element of the pair
            while(left <= right and arr[right] == ele2) {
                right--;
                cnt2++;
            }

            // If both the elements are same, then count of
            // pairs = the number of ways to choose 2 
            // elements among cnt1 elements
            if(ele1 == ele2) 
            	res += (cnt1 * (cnt1 - 1))/2;

            // If the elements are different, then count of
            // pairs = product of the count of both elements
            else 
            	res += (cnt1 * cnt2);
        }
    }
    return res;
}

int main() {
    vector<int> arr = {1, 5, 7, -1, 5};
    int target = 6;

    cout << countPairs(arr, target);

    return 0;
}


